 * For more details on building Java & JVM projects, please refer to https://docs.gradle.org/9.7.1/userguide/building_java_projects.html in the Gradle documentation.
 */

plugins {
    // Apply the application plugin to add support for building a CLI application in Java.
    application
    alias(libs.plugins.shadow)
}

repositories {
    maven {
        url = uri("https://central.sonatype.com/repository/maven-snapshots/")
        mavenContent {
            snapshotsOnly()
        }
    }

    mavenCentral()
}

dependencies {
    // Use JUnit Jupiter for testing.
    testImplementation(libs.junit.jupiter)

    testRuntimeOnly(libs.junit.platform.launcher)

    // This dependency is used by the application.
    implementation(platform(libs.tamboui.bom))
    implementation(libs.tamboui.toolkit)
    implementation(libs.tamboui.panama.backend)
    implementation(libs.clique)
    implementation(libs.guava)
    implementation(libs.picocli)
    implementation(libs.dotenv.java)
    implementation(libs.reactor.netty.http)

    // External packages used by solutions and util.
    implementation(libs.commons.lang3)
    implementation(libs.commons.text)
    implementation(libs.commons.math3)
    implementation(libs.commons.codec)
    implementation(libs.jackson.databind)
    implementation(libs.jackson.datatype.jsr310)
    implementation(libs.jsoup)
    implementation(libs.jgrapht.core)
    implementation(libs.ojalgo)
    implementation(libs.fastutil)
    implementation(libs.jetbrains.annotations)
    implementation(libs.javapoet)
    implementation(libs.jakarta.cdi.api)
    implementation(platform(libs.reactor.bom))
    implementation(libs.reactor.core)

    compileOnly(libs.lombok)
    annotationProcessor(libs.lombok)

    annotationProcessor(libs.picocli.codegen)
}

// Apply a specific Java toolchain to ease working on different environments.
java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(25)
    }
}

application {
    // Define the main class for the application.
    mainClass = "com.vuryss.aoc.App"
    // Panama backend uses FFM (Project Panama) restricted methods; without this
    // the JVM prints a warning on every run and future JDKs will block the calls.
    applicationDefaultJvmArgs = listOf("--enable-native-access=ALL-UNNAMED")
}

tasks.compileJava {
    options.compilerArgs.add("-Aproject=${project.group}/${project.name}")
}

tasks.named<Test>("test") {
    // Use JUnit Platform for unit tests.
    useJUnitPlatform()
}
